@section('script')
<script>
const itemStore=@json(route('user.perpustakaan.catalog.items.store',['userId'=>$userId]));
const itemUpdate=@json(route('user.perpustakaan.catalog.items.update',['userId'=>$userId,'id'=>'__ID__']));
function openItemCreate(){document.getElementById('itemTitle').textContent='Tambah Eksemplar';document.getElementById('itemForm').action=itemStore;document.getElementById('itemMethod').value='POST';['itemCode','itemShelf','itemDate','itemPrice','itemNotes'].forEach(id=>document.getElementById(id).value='');document.getElementById('itemCondition').value='baik';document.getElementById('itemStatus').value='available';}
function openItemEdit(btn){const d=JSON.parse(btn.dataset.item);document.getElementById('itemTitle').textContent='Edit Eksemplar';document.getElementById('itemForm').action=itemUpdate.replace('__ID__',d.id);document.getElementById('itemMethod').value='PUT';document.getElementById('itemTitleWrap').classList.add('d-none');document.getElementById('itemShelf').value=d.shelf_location||'';document.getElementById('itemCondition').value=d.condition||'baik';document.getElementById('itemStatus').value=d.status||'available';document.getElementById('itemNotes').value=d.notes||'';new bootstrap.Modal(document.getElementById('itemModal')).show();}
</script>
@endsection
